{"path": "creative_intent.json", "content": "{
  "user_need": "警察男主绑定\"犯罪预警系统\"，能在凶手额头看到倒计时。他发现未婚妻（法医）额头显示\"将在今晚23:00杀害你\"。系统提示\"不可更改\"。他必须在12小时内破解这个\"未来命案\"，同时不能让她发现他在防备她。随着调查，他发现她杀他的动机是为了阻止他去救一个会导致更大灾难的证人（D20为理想牺牲）。12万字，高密度悬疑。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["牺牲", "防备", "破解", "拯救"],
    "scene_elements": ["警察", "法医", "犯罪预警系统", "倒计时", "证人", "灾难"],
    "relationship_tension": ["未婚夫妻间的信任危机", "为理想牺牲爱情", "隐瞒与防备的双重困境"],
    "user_preferences": {
      "desired_emotion": "高密度悬疑",
      "forbidden": []
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D20",
    "x_axis_mode_name": "为理想牺牲",
    "y_axis_tags": ["系统流", "刑侦悬疑", "规则怪谈"],
    "reaction_strength": "↘",
    "tension_stars": 4,
    "forbidden_elements": ["不要超自然解释", "不要三角恋", "不要主角智商下线"],
    "x_axis_display": "法医未婚妻必须杀死警察男主来阻止他救证人，因为救证人会导致更大灾难",
    "y_axis_combination_effect": "\"犯罪预警系统\"作为规则怪谈式的不可违抗力量，刑侦悬疑提供调查框架，系统流增加倒计时压迫感",
    "reaction_formula": "当\"不可更改\"的系统预言遇上\"为理想牺牲\"的道德困境，信任在倒计时中崩解",
    "platform_fit": ["晋江", "豆瓣阅读", "知乎盐选"]
  },
  "one_sentence_synopsis": "警察发现未婚妻将在今晚23点杀他，而她杀他的动机竟是为了阻止更大的灾难。"
}"}

