        "core_event": "陆沉发现林小雨的身份不简单，而沈清漪似乎知道更多内情",
        "emotional_tone": "迷雾重重",
        "key_scenes": ["证人保护现场", "沈清漪的专业分析", "神秘电话"]
      }
    ],
    "turning_point": "陆沉发现沈清漪深夜独自前往废弃工厂，那里关押着林小雨"
  },
  "act_two": {
    "description": "冲突升级：陆沉深入调查发现更大的阴谋，沈清漪的动机逐渐显露，但时间所剩无几",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "真相的碎片",
        "core_event": "陆沉潜入废弃工厂，发现林小雨掌握着能引发大规模灾难的信息",
        "emotional_tone": "震撼与恐惧",
        "key_scenes": ["工厂潜入", "与林小雨对话", "发现灾难证据"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "为理想牺牲",
        "core_event": "沈清漪向陆沉坦白部分真相：救林小雨会导致更大灾难，她必须阻止他",
        "emotional_tone": "痛苦与挣扎",
        "key_scenes": ["激烈对峙", "部分真相揭露", "情感爆发"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "系统的真相",
        "core_event": "陆沉从陈局处得知犯罪预警系统的真正来源和限制",
        "emotional_tone": "绝望与希望交织",
        "key_scenes": ["局长办公室密谈", "系统档案揭秘", "新的可能性"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "最后的十二小时",
        "core_event": "倒计时进入最后阶段，双方都在为自己的选择做准备",
        "emotional_tone": "紧迫与决绝",
        "key_scenes": ["各自准备", "回忆闪回", "命运交叉点"]
      }
    ],
    "turning_point": "陆沉意识到沈清漪的'杀害'可能不是字面意思，而是某种保护性行动"
  },
  "act_three": {
    "description": "高潮与结局：X-Y化学反应爆发，'不可更改'的预言与'为理想牺牲'的冲突达到顶点",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "23:00",
        "core_event": "在23:00时刻，沈清漪确实'杀害'了陆沉，但方式出人意料",
        "emotional_tone": "震撼与顿悟",
        "key_scenes": ["最终对峙", "真相完全揭露", "牺牲的真谛"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "系统的悖论",
        "core_event": "陆沉发现系统的'不可更改'其实有漏洞，真正的选择在于如何定义'杀害'",
        "emotional_tone": "释然与希望",
        "key_scenes": ["系统重新解读", "两人合作", "危机解除"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "余波",
        "core_event": "灾难被阻止，但两人的关系和对系统的理解都发生了根本改变",
        "emotional_tone": "平静中的新生",
        "key_scenes": ["后续处理", "关系重建", "新的开始"]
      }
    ]
  }
}"}]

